import{At as e,mt as t,n,pt as r}from"./chunks/framework.BrKcMR_c.js";var i=JSON.parse(`{"title":"Glossary","description":"","frontmatter":{"glossary":false},"headers":[],"relativePath":"GLOSSARY.md","filePath":"GLOSSARY.md","lastUpdated":1789092097000}`),a={name:`GLOSSARY.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to “Glossary”">​</a></h1><p>A plain-language guide to the names and concepts used in GOAT. Follow the links for setup instructions and technical detail.</p><h2 id="inference" tabindex="-1">Inference <a class="header-anchor" href="#inference" aria-label="Permalink to “Inference”">​</a></h2><p>Running a model to generate a response. An external engine performs inference; GOAT sends the request and displays the result.</p><p class="goat-gloss-meta">Aliases: inferencing, infer</p><p class="goat-gloss-meta">See: <a href="/reference/engines">Engines</a></p><h2 id="engine" tabindex="-1">Engine <a class="header-anchor" href="#engine" aria-label="Permalink to “Engine”">​</a></h2><p>A server that hosts models and answers GOAT’s requests. It can run on your Mac or at a configured network endpoint; compatibility depends on its API and the selected model.</p><p class="goat-gloss-meta">Aliases: engines, inference engine</p><p class="goat-gloss-meta">See: <a href="/reference/engines">Engines</a></p><h2 id="omlx" tabindex="-1">oMLX <a class="header-anchor" href="#omlx" aria-label="Permalink to “oMLX”">​</a></h2><p>The recommended engine: a native menu-bar app that downloads, manages and serves MLX models on Apple Silicon. GOAT is its client, not its replacement.</p><p class="goat-gloss-meta">See: <a href="/reference/engines">Engines</a></p><h2 id="mlx" tabindex="-1">MLX <a class="header-anchor" href="#mlx" aria-label="Permalink to “MLX”">​</a></h2><p>Apple&#39;s array framework for machine learning on Apple Silicon. Engines like oMLX use it to run models fast on the unified memory of an M-series Mac.</p><h2 id="openai-compatible" tabindex="-1">OpenAI-compatible <a class="header-anchor" href="#openai-compatible" aria-label="Permalink to “OpenAI-compatible”">​</a></h2><p>An API format model servers use for chat requests and responses. GOAT requires a compatible streaming chat endpoint and model list; support for tools, images and reasoning varies.</p><p class="goat-gloss-meta">Aliases: OpenAI-compatible API, OpenAI compatible</p><p class="goat-gloss-meta">See: <a href="/adrs/0017-engine-agnostic-openai-dialect">ADR-0017</a></p><h2 id="model" tabindex="-1">Model <a class="header-anchor" href="#model" aria-label="Permalink to “Model”">​</a></h2><p>The weights an engine loads and runs. Models live with the engine, never inside GOAT or its repo; GOAT lists what the engine serves and picks one per chat.</p><p class="goat-gloss-meta">Aliases: models</p><h2 id="streaming" tabindex="-1">Streaming <a class="header-anchor" href="#streaming" aria-label="Permalink to “Streaming”">​</a></h2><p>Showing a reply as it is generated, token by token. GOAT coalesces those updates to the display&#39;s cadence and checkpoints the transcript to disk about once a second.</p><p class="goat-gloss-meta">Aliases: streams, stream</p><h2 id="token" tabindex="-1">Token <a class="header-anchor" href="#token" aria-label="Permalink to “Token”">​</a></h2><p>A chunk of text a model reads or writes. Its size varies with the model, language and content. Context windows and effort budgets are measured in tokens.</p><p class="goat-gloss-meta">Aliases: tokens</p><h2 id="context-window" tabindex="-1">Context window <a class="header-anchor" href="#context-window" aria-label="Permalink to “Context window”">​</a></h2><p>How much text a model can attend to at once: system prompt, memory digest, tool schemas and transcript together. The pasture meter shows how full it is.</p><p class="goat-gloss-meta">Aliases: context</p><h2 id="thinking" tabindex="-1">Thinking <a class="header-anchor" href="#thinking" aria-label="Permalink to “Thinking”">​</a></h2><p>A model&#39;s visible reasoning before its answer, when the model exposes it. GOAT shows it as a collapsed disclosure; long reasoning stays folded by default.</p><p class="goat-gloss-meta">Aliases: reasoning</p><h2 id="effort" tabindex="-1">Effort <a class="header-anchor" href="#effort" aria-label="Permalink to “Effort”">​</a></h2><p>The dial that sets response budget and sampling per turn: Graze, Trot, Climb or Summit, ⌘1 to ⌘4. The server determines which requested controls it supports.</p><p class="goat-gloss-meta">Aliases: Graze, Trot, Climb, Summit</p><p class="goat-gloss-meta">See: <a href="/reference/engines">Engines</a></p><h2 id="vision-model" tabindex="-1">Vision model <a class="header-anchor" href="#vision-model" aria-label="Permalink to “Vision model”">​</a></h2><p>A model that accepts images as well as text. Paste a screenshot into the composer and GOAT sends it along when the model can see.</p><p class="goat-gloss-meta">Aliases: vision</p><h2 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to “MCP”">​</a></h2><p>Model Context Protocol, the open standard for giving a model tools and resources from external servers. GOAT is an MCP client; every tool call passes a permission gate you control.</p><p class="goat-gloss-meta">Aliases: Model Context Protocol, MCP servers, MCP server</p><p class="goat-gloss-meta">See: <a href="/adrs/0006-mcp-integration">ADR-0006</a></p><h2 id="tool" tabindex="-1">Tool <a class="header-anchor" href="#tool" aria-label="Permalink to “Tool”">​</a></h2><p>A capability the model can call during a turn: an MCP server tool, a memory tool, a skill loader or a bundled extension tool. Tools are typed routes; a name never grants permission.</p><p class="goat-gloss-meta">Aliases: tools, tool call, tool calls</p><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to “Skills”">​</a></h2><p>Read-only Agent Skills, folders with a <code>SKILL.md</code>, loaded from the built-in bundle, <code>~/.goat/skills</code> and each Pen. Instructions are context for the model, never executable code.</p><p class="goat-gloss-meta">Aliases: skill, Agent Skills</p><p class="goat-gloss-meta">See: <a href="/reference/extensions">Extensions</a></p><h2 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to “Memory”">​</a></h2><p>What GOAT remembers between chats. One app-wide provider: Markdown notes in a folder you own (default), a local LLM Wiki, or a Hindsight server. Scoped to Global or one Pen, never both.</p><p class="goat-gloss-meta">See: <a href="/adrs/0005-memory-architecture">ADR-0005</a></p><h2 id="llm-wiki" tabindex="-1">LLM Wiki <a class="header-anchor" href="#llm-wiki" aria-label="Permalink to “LLM Wiki”">​</a></h2><p>A curated local knowledge base the model maintains: immutable sources in <code>raw/</code>, curated pages in <code>wiki/</code>, an index and a log. An optional memory provider.</p><p class="goat-gloss-meta">See: <a href="/llm-wiki-contract">LLM wiki contract</a></p><h2 id="hindsight" tabindex="-1">Hindsight <a class="header-anchor" href="#hindsight" aria-label="Permalink to “Hindsight”">​</a></h2><p>An optional external memory service. GOAT can recall knowledge and retain chat context in a configured bank; the server’s storage and network behaviour are controlled separately.</p><p class="goat-gloss-meta">See: <a href="/adrs/0036-native-skills-and-hindsight-lifecycle">ADR-0036</a></p><h2 id="herd-guarantee" tabindex="-1">Herd Guarantee <a class="header-anchor" href="#herd-guarantee" aria-label="Permalink to “Herd Guarantee”">​</a></h2><p>The product invariant: GOAT&#39;s own code never phones home. No analytics, no update pings, no crash reports. Configured services, permitted preview content and explicitly approved command networking have separate network boundaries.</p><p class="goat-gloss-meta">See: <a href="/adrs/0015-preview-network-policy">ADR-0015</a></p><h2 id="herd" tabindex="-1">Herd <a class="header-anchor" href="#herd" aria-label="Permalink to “Herd”">​</a></h2><p>The whole flock: the project, the release codename family, and your Herd workspaces, the real working folders a Pen can bind to.</p><p class="goat-gloss-meta">Aliases: Herd workspace, Herd workspaces</p><p class="goat-gloss-meta">See: <a href="/adrs/0032-herd-workspaces-and-read-only-git-status">ADR-0032</a></p><h2 id="pen" tabindex="-1">Pen <a class="header-anchor" href="#pen" aria-label="Permalink to “Pen”">​</a></h2><p>A project that groups chats, instructions, skills and memory. Its configuration lives under <code>~/.goat/projects/</code>; it can also bind to a working folder with separate file and command permissions.</p><p class="goat-gloss-meta">Aliases: Pens</p><p class="goat-gloss-meta">See: <a href="/adrs/0019-pens-as-folders">ADR-0019</a></p><h2 id="paddock" tabindex="-1">Paddock <a class="header-anchor" href="#paddock" aria-label="Permalink to “Paddock”">​</a></h2><p>The inspector for HTML, SVG, Mermaid, Markdown and code produced during a chat. Web previews run with a separate content and connection policy.</p><p class="goat-gloss-meta">See: <a href="/adrs/0010-paddock-artifacts">ADR-0010</a></p><h2 id="off-grid-previews" tabindex="-1">Off-grid previews <a class="header-anchor" href="#off-grid-previews" aria-label="Permalink to “Off-grid previews”">​</a></h2><p>A Paddock setting that restricts preview connections to permitted local resources. JUDAS can impose stricter restrictions; blocked resources may leave a preview incomplete.</p><p class="goat-gloss-meta">Aliases: off-grid</p><p class="goat-gloss-meta">See: <a href="/adrs/0015-preview-network-policy">ADR-0015</a></p><h2 id="judas" tabindex="-1">JUDAS <a class="header-anchor" href="#judas" aria-label="Permalink to “JUDAS”">​</a></h2><p>GOAT’s connection policy for engines, MCP, Hindsight and preview content, with decisions recorded in the Activity Log. It is not a system firewall or a complete network traffic capture.</p><p class="goat-gloss-meta">See: <a href="/adrs/0045-judas-central-egress-policy">ADR-0045</a></p><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to “Activity Log”">​</a></h2><p>The read-only log panel (⌃`): engine, MCP, memory and JUDAS events with timestamps. Not a terminal, and not a tamper-evident journal.</p><p class="goat-gloss-meta">See: <a href="/adrs/0014-activity-log-not-terminal">ADR-0014</a></p><h2 id="shepherd" tabindex="-1">Shepherd <a class="header-anchor" href="#shepherd" aria-label="Permalink to “Shepherd”">​</a></h2><p>The actor that runs one turn: plan the prompt, stream, run tool calls behind the permission gate, persist, hand off to memory. The only place inference, tools and memory meet.</p><p class="goat-gloss-meta">See: <a href="/reference/architecture">Architecture</a></p><h2 id="goated" tabindex="-1">GOATed <a class="header-anchor" href="#goated" aria-label="Permalink to “GOATed”">​</a></h2><p>GOAT Extension Dynamics: the typed, in-process extension runtime. Scoped, atomic, revocable registrations; bundled Swift only in Kid. Surfaced as Settings → Extensions.</p><p class="goat-gloss-meta">Aliases: extensions, extension</p><p class="goat-gloss-meta">See: <a href="/reference/extensions">Extensions</a></p><h2 id="hitch" tabindex="-1">Hitch <a class="header-anchor" href="#hitch" aria-label="Permalink to “Hitch”">​</a></h2><p>The optional local control API and the <code>goat</code> command line tool. A Unix socket owned by the running app, same user only, off by default. No TCP, no daemon.</p><p class="goat-gloss-meta">Aliases: goat CLI</p><p class="goat-gloss-meta">See: <a href="/adrs/0043-local-goat-control-and-cli">ADR-0043</a></p><h2 id="herder" tabindex="-1">Herder <a class="header-anchor" href="#herder" aria-label="Permalink to “Herder”">​</a></h2><p>The built-in extension for workspace file operations and confined commands. File and command permissions are controlled separately for each Pen, with approval scopes for individual actions, a chat or future Pen work.</p><p class="goat-gloss-meta">See: <a href="/how-to/WORK-ON-CODE">Work on code</a></p><h2 id="pronk" tabindex="-1">Pronk <a class="header-anchor" href="#pronk" aria-label="Permalink to “Pronk”">​</a></h2><p>The bundled example extension: one fictional goat per Pen that accepts treats and counts adventures. A pronk is a goat&#39;s celebratory stiff-legged jump.</p><p class="goat-gloss-meta">See: <a href="/Pronk-Example">Pronk example</a></p><h2 id="tether" tabindex="-1">Tether <a class="header-anchor" href="#tether" aria-label="Permalink to “Tether”">​</a></h2><p>A proposed inspector module for configuring image and video generation. Documented in ADR-0029, not yet built.</p><p class="goat-gloss-meta">See: <a href="/adrs/0029-contextual-media-workspaces-and-tether">ADR-0029</a></p><h2 id="caprine" tabindex="-1">Caprine <a class="header-anchor" href="#caprine" aria-label="Permalink to “Caprine”">​</a></h2><p>Of or relating to goats. Also GOAT&#39;s design language: semantic colour tokens, a 4 pt grid, spring motion and a personality budget.</p><p class="goat-gloss-meta">See: <a href="/DESIGN">Design</a></p><h2 id="theme" tabindex="-1">Theme <a class="header-anchor" href="#theme" aria-label="Permalink to “Theme”">​</a></h2><p>A look for GOAT as data: one folder, one <code>theme.json</code> in the GOAT Theme Format. Built-ins are System, Light, Pasture and Midnight; duplicate one to edit it.</p><p class="goat-gloss-meta">Aliases: themes, GTF, GOAT Theme Format</p><p class="goat-gloss-meta">See: <a href="/THEMES">Themes</a></p><h2 id="liquid-glass" tabindex="-1">Liquid Glass <a class="header-anchor" href="#liquid-glass" aria-label="Permalink to “Liquid Glass”">​</a></h2><p>Apple&#39;s macOS 26 material: translucent, refractive surfaces that show what sits behind the window. GOAT uses the real thing, not a blurred screenshot.</p><h2 id="kid" tabindex="-1">Kid <a class="header-anchor" href="#kid" aria-label="Permalink to “Kid”">​</a></h2><p>The 0.1 release line, including its 0.1.1 maintenance update. Patch releases retain Kid; Yearling is reserved for the planned 0.2 polish release. Later codenames include Billy, Nanny, Wether, Ram, Capra and Ibex at 1.0.</p><p class="goat-gloss-meta">Aliases: 0.1 (Kid)</p><p class="goat-gloss-meta">See: <a href="/CODENAMES">Codenames</a></p><h2 id="goat-home" tabindex="-1">GOAT home <a class="header-anchor" href="#goat-home" aria-label="Permalink to “GOAT home”">​</a></h2><p>The folder GOAT keeps your files in: <code>~/.goat</code> by default, or <code>GOAT_HOME</code>. Config, memory, skills, Pens and themes all live here, in plain files you own.</p><p class="goat-gloss-meta">Aliases: ~/.goat, GOAT_HOME</p><p class="goat-gloss-meta">See: <a href="/adrs/0009-goat-home-and-mcp-config">ADR-0009</a></p><h2 id="_1337" tabindex="-1">1337 <a class="header-anchor" href="#_1337" aria-label="Permalink to “1337”">​</a></h2><p>The unlockable playful presentation: type <code>1337</code> in About for the alternate icons, the 1337 theme and the mascot. A preference only; it never changes behaviour.</p><p class="goat-gloss-meta">See: <a href="/adrs/0038-professional-presentation-gate">ADR-0038</a></p><h2 id="bleet" tabindex="-1">Bleet <a class="header-anchor" href="#bleet" aria-label="Permalink to “Bleet”">​</a></h2><p>The chat domain module. Owns session and message state, streaming display revisions and incremental live metrics. Shepherd coordinates its turns.</p><p class="goat-gloss-meta">See: <a href="/MODULES#bleet">Modules</a></p><h2 id="hoofprint" tabindex="-1">Hoofprint <a class="header-anchor" href="#hoofprint" aria-label="Permalink to “Hoofprint”">​</a></h2><p>The activity and diagnostics module. Owns the bounded in-memory Activity Log and local Instruments signposts. It sends no telemetry.</p><p class="goat-gloss-meta">See: <a href="/MODULES#hoofprint">Modules</a></p>',131)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};